package edu.pe.cibertec.saibm.libro.rest;
import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*; import java.util.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest; import org.springframework.boot.test.mock.mockito.MockBean; import org.springframework.context.annotation.Import; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import edu.pe.cibertec.saibm.libro.application.port.in.BookUseCase; import edu.pe.cibertec.saibm.libro.infrastructure.in.rest.*;
@WebMvcTest(BookController.class) @Import(LibroExceptionHandler.class) class LibroRestTest { @Autowired MockMvc mvc; @MockBean BookUseCase books; @MockBean TransitionalWriteAuthorizer auth; final UUID id=UUID.randomUUID(); final BookUseCase.View view=new BookUseCase.View(id,"Java","","Ada","",true); @Test void searchExposesMetadataOnly() throws Exception {when(books.search(any())).thenReturn(new BookUseCase.Page(List.of(view),0,20,1,1));mvc.perform(get("/api/v1/books").param("q"," java ")).andExpect(status().isOk()).andExpect(jsonPath("$.content[0].id").value(id.toString())).andExpect(jsonPath("$.content[0].active").value(true)).andExpect(jsonPath("$.content[0].totalStock").doesNotExist());} @Test void writesFailClosedWithoutSignedBoundary() throws Exception {doThrow(new WriteAuthorizationException()).when(auth).require(any());mvc.perform(post("/api/v1/books").contentType(MediaType.APPLICATION_JSON).content("{\"title\":\"Java\",\"author\":\"Ada\"}")).andExpect(status().isForbidden()).andExpect(jsonPath("$.status").value(403));} @Test void validCreateReturnsDto() throws Exception {when(books.create(any())).thenReturn(view);mvc.perform(post("/api/v1/books").contentType(MediaType.APPLICATION_JSON).content("{\"title\":\"Java\",\"author\":\"Ada\"}")).andExpect(status().isCreated()).andExpect(jsonPath("$.id").value(id.toString()));} }
